/* * @lc app=leetcode id=1576 lang=kotlin * * [1576] Replace All ?'s to Avoid Consecutive Repeating Characters */ class Solution { fun modifyString(s: String): String = s.toCharArray().apply { indices.filter { get(it) == '?' }.forEach { i -> this[i] = charArrayOf('a', 'b', 'c').first { c -> (i == 0 || get(i - 1) != c) && (i == lastIndex || get(i + 1) != c) } } }.concatToString() }